/** Wire value -> SDK value for the named type; a name that is not a type returns the value as is. */
export function decode(value: unknown, name: string): unknown {
  const fn = DECODERS[name];
  return fn ? fn(value) : value;
}

/** SDK value -> wire value: exact scalars as strings (toWire), then the contract's field names. */
export function encode(value: unknown, name: string): unknown {
  const wire = c.toWire(value);
  const fn = ENCODERS[name];
  return fn ? fn(wire) : wire;
}
